<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('sales');$pageTitle='Sales Targets';$activeMenu='sales-target';$errors=[];
if(isset($_GET['delete'])){$token=$_GET['token']??'';if(!hash_equals(csrf_token(),$token)){http_response_code(419);exit('Invalid token');}db()->prepare('DELETE FROM sales_targets WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Target deleted.');redirect('sales/targets.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$person=(int)$_POST['salesperson_id'];$dept=(int)$_POST['department_id'];$month=$_POST['target_month'].'-01';$amount=(float)$_POST['target_amount'];if(!$person||!$dept||!valid_date($month)||$amount<=0)$errors[]='Complete all fields with valid values.';if(!$errors){$s=db()->prepare('INSERT INTO sales_targets(salesperson_id,department_id,target_month,target_amount,created_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE department_id=VALUES(department_id),target_amount=VALUES(target_amount),updated_at=NOW()');$s->execute([$person,$dept,$month,$amount,current_user()['id']]);log_activity('UPSERT','Sales Target','Saved target for user #'.$person);flash('success','Sales target saved.');redirect('sales/targets.php');}}
$rows=db()->query("SELECT st.*,CONCAT(u.first_name,' ',u.last_name) person,d.name department FROM sales_targets st JOIN users u ON u.id=st.salesperson_id JOIN departments d ON d.id=st.department_id ORDER BY st.target_month DESC,person")->fetchAll();$users=users_for_select();$departments=departments();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Sales Targets</h1><p>Define measurable monthly targets per salesperson.</p></div></div><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="row g-3"><div class="col-lg-4"><div class="card-panel"><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Sales Person</label><select class="form-select" name="salesperson_id" required><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Department</label><select class="form-select" name="department_id"><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Month</label><input class="form-control" type="month" name="target_month" value="<?=e(date('Y-m'))?>"></div><div class="mb-3"><label class="form-label">Target Amount</label><input class="form-control" type="number" step=".01" min=".01" name="target_amount"></div><button class="btn btn-primary w-100">Save Target</button></form></div></div></div><div class="col-lg-8"><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Month</th><th>Sales Person</th><th>Department</th><th class="text-end">Target</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('M Y',strtotime($r['target_month'])))?></td><td><?=e($r['person'])?></td><td><?=e($r['department'])?></td><td class="text-end"><?=money($r['target_amount'])?></td><td><a data-confirm="Delete this target?" class="btn btn-sm btn-light border text-danger" href="<?=e(url('sales/targets.php?delete='.$r['id'].'&token='.csrf_token()))?>"><i class="fa-solid fa-trash"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
